// La API devuelve { result: 'success', rates: { USD: 1, BOB: ..., EUR: ... }, time_last_update_utc, ... }
const api = $input.first().json;
const pedido = $('Qué convertir').first().json;

const fuente = 'Rates By Exchange Rate API (https://www.exchangerate-api.com)';
if (api.result !== 'success' || !api.rates) {
  return [{ json: { ok: false, error: 'La API de cotizaciones no respondió bien: ' + (api['error-type'] ?? 'sin detalle') + '. Probá de nuevo en unos minutos.', fuente } }];
}
const tasas = api.rates;

// El monto puede venir como «1.500,50», «1500.5» o «100»: lo pasamos a número.
const texto = String(pedido.monto ?? '').trim();
const normalizado = texto.includes(',') ? texto.replace(/\./g, '').replace(',', '.') : texto;
const monto = Number(normalizado);

const errores = [];
if (!texto || !Number.isFinite(monto) || monto < 0) errores.push(`el monto «${texto}» no es un número válido`);
if (!tasas[pedido.de]) errores.push(`la moneda «${pedido.de}» no está en la lista (usá códigos de 3 letras, como USD, BOB, EUR, BRL)`);
if (!tasas[pedido.a]) errores.push(`la moneda «${pedido.a}» no está en la lista`);
if (errores.length) return [{ json: { ok: false, error: 'Revisá el pedido: ' + errores.join('; ') + '.', fuente } }];

const redondear = (n, d = 2) => Math.round(n * 10 ** d) / 10 ** d;
const tasa = tasas[pedido.a] / tasas[pedido.de]; // cuánto vale 1 «de» en «a»
const resultado = monto * tasa;

// Fecha de la cotización, en hora de Bolivia.
const actualizada = DateTime.fromSeconds(api.time_last_update_unix).setZone('America/La_Paz').setLocale('es');

// Referencias del día: cuántos bolivianos vale 1 unidad de cada moneda.
const referencias = {};
for (const m of ['USD', 'EUR', 'BRL', 'ARS', 'PEN', 'CLP']) {
  if (tasas[m]) referencias[m] = redondear(tasas.BOB / tasas[m], 4);
}

return [{
  json: {
    ok: true,
    monto,
    de: pedido.de,
    a: pedido.a,
    resultado: redondear(resultado),
    tasa: redondear(tasa, 6),
    dolar_en_bolivianos: redondear(tasas.BOB, 4),
    referencias_en_bolivianos: referencias,
    cotizacion_del: actualizada.toFormat("d 'de' LLLL 'de' yyyy, HH:mm"),
    origen: pedido.origen,
    fuente,
  },
}];
